"""PATH-QC-N59-5 combined native59 kit, generated by THIS commit's flow (tools/die_plan/gen.py phys; watched flow files
equal the released QC canary src 1d335f9d99) + N59 kit-local hooks (no watched tool file carries N59 code):
  fix (3)  results/qc_n59_2145/inputs/rtl/qfd_native59_svc_obs1.sv (emb_go/cmd_bad registered beside p_cmd, 0 cycles)
  fix (2)  SYNTH_CANONICALIZE = n59_keep_replicas (Codex driver keep) + physical/common_flow/ot_keep_regs.tcl (-> ot_rst_copies.tcl)
           (OT_RST_COPIES_MAX 200, RE (^|[.])rst_cp_[a-z0-9]+$)
  fix (1)  joint complete-cone anchors n59_reach405.tcl, regenerated BY NAME on this kit's own netlist
           (--anchors <entries file>; without it pre_gpl refuses to place).
Usage: python3 build_kit.py --out DIR [--anchors ENTRIES]    (--install-anchors ENTRIES --out DIR: only (re)write anchors)
"""
import argparse,shutil,subprocess,sys
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--out',required=True);p.add_argument('--anchors');p.add_argument('--install-anchors')
a=p.parse_args()
root=Path(__file__).resolve().parents[3];here=Path(__file__).resolve().parent;packet=here.parent
out=Path(a.out).resolve();k=out/'native59'
def install(entries):
    hdr=(packet/'inputs/hooks/n59_reach405.tcl').read_text().split('\n')
    i0=next(i for i,l in enumerate(hdr) if l.startswith('set n59r_entries {'));i1=next(i for i in range(i0+1,len(hdr)) if hdr[i]=='}')
    rows=[l for l in Path(entries).read_text().split('\n') if l.startswith(' {{')]
    body=hdr[:i0]+['# PATH-QC-N59-5 %d anchors from %s (joint complete-cone model on this kit netlist)'%(len(rows),Path(entries).name),hdr[i0]]+rows+hdr[i1:]
    (k/'n59_reach405.tcl').write_text('\n'.join(body))
    print('anchors installed',len(rows))
if a.install_anchors:
    install(a.install_anchors);sys.exit(0)
subprocess.run([sys.executable,'-I',str(root/'tools/die_plan/gen.py'),'phys',str(root/'physical/die_plan/qwen_compute/die_plan.json'),
  '--out',str(out),'--types','native59','--rtl-root',str(root),'--kit-rtl','native59='+str(packet/'inputs/files.f'),'--hold-ff-margin','5'],cwd=root,check=True)
for d in (packet/'inputs/hooks',here/'hooks'):
    for h in d.glob('*.tcl'):shutil.copyfile(h,k/h.name)
shutil.copytree(root/'physical/common_flow',k/'cf',dirs_exist_ok=True)
(k/'n59_canon_rst.tcl').write_text('# PATH-QC-N59-5: Codex driver-keep canonicalisation, then the STANDARD keep hook physical/common_flow/ot_keep_regs.tcl\n'
 '# (per-bit techmap + keep on every cell driving a keep wire, then ot_rst_copies.tcl because OT_RST_COPIES_MAX is set;\n'
 '# GEOM-REVIEW-11 23:44 fix (2)).  Sourcing ot_rst_copies.tcl alone (N59-4 rstB, N59-5 first synth) split the loads but\n'
 '# the vector rst_cp_* cells had keep only as multi-bit cells: techmap split them without keep and opt_merge folded every\n'
 '# family back to copy [0] (10 rst_cp flops in 1_2_yosys.v; rstB reset census 3901 pins > 405 um).\n'
 'source /work/n59_keep_replicas.tcl\nsource /work/cf/ot_keep_regs.tcl\n')
(k/'pre_gpl.tcl').write_text('source /work/face_flops.tcl\nsource /work/n59_stations.tcl\nsource /work/cf/macro_pin_flops.tcl\nsource /work/n59_reach405.tcl\n')
(k/'pre_dpl.tcl').write_text('source /work/face_flops_release.tcl\nsource /work/n59_stations_release.tcl\nsource /work/cf/macro_pin_flops_release.tcl\nsource /work/n59_reach405.tcl\n')
c=(k/'config.mk').read_text()
for old,new in (('export VERILOG_DEFINES = -DSYNTHESIS','export VERILOG_DEFINES = -DSYNTHESIS -DOT_N59_WIF -DOT_N59_STN'),
                ('export PRE_GLOBAL_PLACE_TCL = /work/face_flops.tcl','export PRE_GLOBAL_PLACE_TCL = /work/pre_gpl.tcl'),
                ('export PRE_DETAIL_PLACE_TCL = /work/face_flops_release.tcl','export PRE_DETAIL_PLACE_TCL = /work/pre_dpl.tcl'),
                ('export PRE_SYNTH_TCL = /work/face_keep.tcl','export PRE_SYNTH_TCL = /work/n59_keep_odb.tcl'),
                ('export POST_SYNTH_TCL = /work/face_keep_release.tcl','export POST_SYNTH_TCL = /work/n59_keep_odb_release.tcl')):
    assert c.count(old)==1,old;c=c.replace(old,new)
assert 'SYNTH_CANONICALIZE_TCL' not in c
c+=('\n# PATH-QC-N59-5 kit-local N59 hooks\nexport MIN_CLK_ROUTING_LAYER = M6\nexport MAX_CLK_ROUTING_LAYER = M7\n'
    'export SYNTH_CANONICALIZE_TCL = /work/n59_canon_rst.tcl\nexport OT_RST_COPIES_MAX = 200\nexport OT_RST_COPIES_RE = (^|[.])rst_cp_[a-z0-9]+$$\n')
(k/'config.mk').write_text(c)
if a.anchors:install(a.anchors)
else:(k/'n59_reach405.tcl').write_text('error "N59_REACH405 anchors not installed: build_kit.py --install-anchors"\n')
print(k)
